formData.jsFunction:
def validate(request, response = [:], regexMap = [:]) {
    if (request.classifier == "null") {
        response.classifier = "Please provide a proper classifier. The classifier is missing"
    }

    def hasTables = request.tables
    def hasColumns = request.columns
    if (hasTables && validateAlias(request, "tables", regexMap)) {
        response.message = request.error
    }

    if (hasColumns && validateAlias(request, "columns", regexMap)) {
        response.message = request.error
        return response
    }

    if (request.containsKey("access")) {
        return validateAccess(request, response)
    }

    return response
}


def validateAlias(request, keyName, regexMap = [:]) {
    def tableColumnKey = request[keyName]
    def aliasPattern = regexMap?.metadataAlias ?: regexMap?.aliasName
    boolean invalid = false
    tableColumnKey.each { key, columnName ->
        if (invalid || columnName == null) return
        if (columnName.startsWith(" ")) {
            request.error = "Alias should not start with spaces"
            invalid = true
        } else if (columnName.equals("")) {
            request.error = "The alias name cannot be blank"
            invalid = true
        } else if (aliasPattern && !columnName.matches(aliasPattern)) {
            request.error = "Invalid characters found only " + '.$()[]\'_-* allowed'
            invalid = true
        }
    }
    return invalid
}

def validateAccess(request, response) {

    if (!(request.access instanceof Map)) {
        response.access = "The  'access'  in the formData should be a JSON object"
        return response
    }

    def accessObject = request.access
    if (!accessObject.containsKey("expression")) {
        response.access = "The  'expression' in 'access' is missing"
        return response
    }

    if (!(accessObject.expression instanceof List)) {
        response.expression = "Expected 'expression' in 'access' to be a JSON array "
        return response
    }

    def expressionArray = accessObject.expression
    Set<String> duplicate = new HashSet<String>()
    for (expressionJson in expressionArray) {
        if (!expressionJson.containsKey("expressionId")) {
            response.access = "The  'expressionId' in 'expression' array is missing"
            return response
        }

        def expressionId = expressionJson.expressionId
        if (expressionId.isEmpty()) {
            response.expressionId = "The  'expressionId' in 'expression' cannot be blank"
            return response
        }

        if (!duplicate.add(expressionId)) {
            response.expressionId = "The  duplicate expression id " + duplicate + "  found"
            return response
        }

        if (!expressionJson.containsKey("action")) {
            response.access = "The  'action' in 'expression' is missing"
            return response
        }

        if (expressionJson.action.isEmpty()) {
            response.access = "The  'action' in 'expression' cannot be blank"
            return response
        }
    }
    return response
}
